package com.example.examplemod.cargo.center;

import com.example.examplemod.cargo.*;
import com.example.examplemod.city.CityManager;
import com.example.examplemod.economy.EconomyManager;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;

/** Autonomous trade uses physical Create orders; import intentions are persisted before creation. */
@EventBusSubscriber(modid="createcityexpansioncore")
public final class MasterCityTradeService {
    private static final ZoneId ZONE=ZoneId.of("Europe/Minsk");
    private record SupplyQuote(UUID token,long expires,UUID contract,CargoWarehouseRegistry.Warehouse source,int quantity,OwnerRef supplier,long goods,CargoRoutePlanner.Route route) {}
    private static final Map<ServerPlayer,SupplyQuote> QUOTES=new WeakHashMap<>();
    private MasterCityTradeService(){}
    public static MasterCityTradeBook book(MinecraftServer s){return EconomyManager.get(s.overworld()).masterTrade();}
    public static OwnerRef payer(){return new OwnerRef(OwnerRef.Kind.FOREIGN_TRADE,MasterCityTradeBook.ACCOUNT_ID);}
    public static void clock(MinecraftServer s){long now=System.currentTimeMillis();book(s).time(now,Instant.ofEpochMilli(now).atZone(ZONE).toLocalDate().toEpochDay());}
    public static CargoWarehouseRegistry.Warehouse warehouse(MinecraftServer s){var b=book(s).binding();if(b==null)throw new IllegalArgumentException("master_not_bound");var w=CargoWarehouseRegistry.get(s).find(b.warehouse()).orElseThrow(()->new IllegalArgumentException("master_warehouse_missing"));var owner=CargoWarehouseRegistry.access(s,w).owner();if(owner.kind()!=OwnerRef.Kind.CITY||!owner.id().equals(b.city())||!w.point().equals(b.point())||CityManager.get(s.overworld()).getCity(b.city())==null)throw new IllegalArgumentException("master_binding_changed");if(CargoWarehouseRegistry.ticker(s,w)==null||!CargoWarehouseRegistry.nativeAuthorized(s,w)||CargoWarehouseRegistry.receivingInventory(s,w)==null)throw new IllegalArgumentException("master_infrastructure_unavailable");return w;}
    public static int stock(MinecraftServer s,CargoWarehouseRegistry.Warehouse w,ItemStack item){var ticker=CargoWarehouseRegistry.ticker(s,w);return ticker==null?0:Math.max(0,ticker.getAccurateSummary().getCountOf(item));}
    public static boolean pendingImport(MinecraftServer s,UUID warehouse){var b=book(s);return b.binding()!=null&&b.binding().warehouse().equals(warehouse)&&b.imports().stream().anyMatch(i->i.state()==MasterCityTradeBook.ImportState.INTENT||i.state()==MasterCityTradeBook.ImportState.APPLIED||i.state()==MasterCityTradeBook.ImportState.QUARANTINED);}
    public static void ensureSourceReady(MinecraftServer s,CargoWarehouseRegistry.Warehouse w){validateConfirmedImports(s,w);if(pendingImport(s,w.id()))throw new IllegalArgumentException("master_import_reconciliation_required");}
    static boolean needsReceipt(CargoCommerceBook.Offer offer,Collection<CargoCommerceBook.Order> orders,UUID id){return offer!=null&&offer.active()&&offer.remaining()>0||orders.stream().anyMatch(o->id.equals(o.offer())&&o.state()!=CargoCommerceBook.State.SETTLED&&o.state()!=CargoCommerceBook.State.CANCELLED&&o.state()!=CargoCommerceBook.State.REFUNDED);}
    private static boolean needsReceipt(MinecraftServer s,MasterCityTradeBook.ImportBatch batch){if(batch.offer()==null)return false;var commerce=EconomyManager.get(s.overworld()).cargo();return needsReceipt(commerce.offer(batch.offer()).orElse(null),commerce.orders(),batch.offer());}
    private static void validateConfirmedImports(MinecraftServer s,CargoWarehouseRegistry.Warehouse w){var b=book(s);if(b.binding()==null||!w.id().equals(b.binding().warehouse()))return;for(var batch:b.imports())if(batch.state()==MasterCityTradeBook.ImportState.CONFIRMED&&needsReceipt(s,batch)){var level=s.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,batch.buffer().dimension()));if(level==null||!level.hasChunkAt(batch.buffer().pos()))throw new IllegalArgumentException("master_buffer_unavailable");var target=batch.buffer().loaded(s);var receipt=target instanceof MasterCityCustomsBufferBlockEntity be&&be.instanceId().equals(b.binding().bufferInstance())?be.buffer().receipt(batch.id()):new CompoundTag();if(!MasterCityImportReceipts.matches(receipt,batch.id(),batch.item(),batch.quantity())){EconomyManager.get(s.overworld()).cargo().close(batch.offer());b.quarantineImport(batch.id(),"master_import_receipt_missing");if(target instanceof MasterCityCustomsBufferBlockEntity be)be.buffer().quarantine("master_import_receipt_missing");throw new IllegalArgumentException("master_import_receipt_missing");}}}
    public static MasterCityCustomsBufferBlockEntity buffer(MinecraftServer s){var b=book(s).binding();if(b==null||!(b.buffer().loaded(s) instanceof MasterCityCustomsBufferBlockEntity be)||be.isRemoved()||!be.instanceId().equals(b.bufferInstance()))throw new IllegalArgumentException("master_customs_buffer_missing");return be;}
    public static void bind(ServerPlayer actor,UUID city,UUID warehouse){requireOp(actor);var s=actor.getServer();if(book(s).imports().stream().anyMatch(i->needsReceipt(s,i)))throw new IllegalArgumentException("master_active_obligations");var w=CargoWarehouseRegistry.get(s).find(warehouse).orElseThrow();var owner=CargoWarehouseRegistry.access(s,w).owner();if(owner.kind()!=OwnerRef.Kind.CITY||!owner.id().equals(city)||CityManager.get(s.overworld()).getCity(city)==null)throw new IllegalArgumentException("master_warehouse_owner");if(CargoWarehouseRegistry.receivingInventory(s,w)==null||CargoWarehouseRegistry.ticker(s,w)==null||!CargoWarehouseRegistry.nativeAuthorized(s,w))throw new IllegalArgumentException("master_infrastructure_unavailable");if(!(CargoInfrastructure.lookedAt(actor) instanceof MasterCityCustomsBufferBlockEntity customs))throw new IllegalArgumentException("master_look_at_customs_buffer");if(customs.buffer().locked())throw new IllegalArgumentException("master_buffer_full_or_locked");book(s).bind(new MasterCityTradeBook.Binding(city,w.point(),w.id(),new CargoInfrastructure.Location(actor.level().dimension().location(),customs.getBlockPos()),customs.instanceId()),actor.getUUID());EconomyManager.get(s.overworld()).setMasterCity(city);}
    public static void requireOp(ServerPlayer actor){if(!actor.hasPermissions(2))throw new IllegalArgumentException("master_operator_required");}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){var s=event.getServer();if(s.overworld().getGameTime()%20!=0)return;clock(s);reconcile(s);if(book(s).enabled()&&s.overworld().getGameTime()%1200==0)try{run(s,null);}catch(IllegalArgumentException|NoSuchElementException invalid){book(s).note(null,"WAIT",Objects.toString(invalid.getMessage(),"infrastructure unavailable"));}}
    public static void run(MinecraftServer s,UUID actor){
        clock(s);var b=book(s);if(!b.enabled())throw new IllegalArgumentException("master_paused");var w=warehouse(s);int work=0;
        for(var p:b.policies()){
            if(work>=4)break;var item=ItemStack.parseOptional(s.registryAccess(),p.item());if(item.isEmpty()||p.direction()==MasterCityTradeBook.Direction.OFF)continue;
            int onHand=stock(s,w,item),inbound=b.inbound(p.id()),deficit=(int)Math.max(0L,(long)p.target()-onHand-inbound);long since=b.shortage(p.id(),deficit>0);if(deficit==0)continue;
            boolean delayed=b.now()-since>=p.delayMillis();boolean suppliers=hasSupplier(s,p,item);
            if(p.direction()==MasterCityTradeBook.Direction.BOTH&&delayed&&!suppliers)for(var c:b.contracts())if(c.policy().equals(p.id())&&c.state()==MasterCityTradeBook.ContractState.OPEN)b.closeContract(c.id(),true,actor);
            boolean useImport=p.direction()==MasterCityTradeBook.Direction.IMPORT||p.direction()==MasterCityTradeBook.Direction.BOTH&&delayed&&!suppliers&&!b.hasOpen(p.id());
            int count=p.demand(onHand,inbound,b.quotaUsed(p.id()));if(count<1)continue;
            try{
                if(useImport){if(!delayed||b.hasOpen(p.id())||b.imports().stream().anyMatch(i->i.state()==MasterCityTradeBook.ImportState.INTENT||i.state()==MasterCityTradeBook.ImportState.APPLIED))continue;if(importGoods(s,p,count,actor))work++;}
                else {if(b.hasOpen(p.id())||citySaleCrosses(s,p,item))continue;long affordable=Math.max(0,b.remainingBudget()-p.maximumFreight())/p.buyPrice();count=(int)Math.min(count,affordable);if(count<1)continue;var c=b.createContract(stable("contract/"+b.period()+"/"+p.id()+"/"+(b.now()/60_000)),p.id(),count,p.partner()+" · "+p.name(),Math.addExact(b.now(),p.durationMillis()),actor);work++;if(p.automatic())automatic(s,c);}
            }catch(IllegalArgumentException|NoSuchElementException|ArithmeticException invalid){b.note(actor,"WAIT",p.name()+": "+Objects.toString(invalid.getMessage(),"unavailable"));}
        }
        for(var c:b.contracts())if(c.state()==MasterCityTradeBook.ContractState.OPEN&&c.expires()>b.now()&&b.policy(c.policy()).orElseThrow().automatic())try{automatic(s,c);}catch(IllegalArgumentException|NoSuchElementException invalid){b.note(actor,"WAIT",c.name()+": "+Objects.toString(invalid.getMessage(),"unavailable"));}
    }
    private static boolean hasSupplier(MinecraftServer s,MasterCityTradeBook.Policy p,ItemStack item){var b=book(s);int checked=0;for(var o:EconomyManager.get(s.overworld()).cargo().offers()){if(!o.active()||o.remaining()<1||o.unitPrice()>p.buyPrice()||o.owner().kind()==OwnerRef.Kind.CITY&&o.owner().id().equals(b.binding().city())||!ItemStack.isSameItemSameComponents(item,ItemStack.parseOptional(s.registryAccess(),o.item())))continue;if(++checked>32)break;var source=CargoWarehouseRegistry.get(s).find(o.warehouse()).orElse(null);if(source==null||CargoFulfillment.available(s,source,item)<1||!CargoOwners.permits(s,payer(),CargoOwners.get(s).access("offer/"+o.id(),o.creator(),CargoTrainRegistry.AccessMode.PUBLIC)))continue;if(CargoRoutePlanner.plan(s,payer(),source.point(),b.binding().point(),CargoRoutePlanner.Preference.CHEAPEST,"ANY",1,item).isPresent())return true;}return false;}
    private static boolean citySaleCrosses(MinecraftServer s,MasterCityTradeBook.Policy p,ItemStack item){var b=book(s);return EconomyManager.get(s.overworld()).cargo().offers().stream().anyMatch(o->o.active()&&o.remaining()>0&&o.owner().kind()==OwnerRef.Kind.CITY&&o.owner().id().equals(b.binding().city())&&o.unitPrice()<=p.buyPrice()&&ItemStack.isSameItemSameComponents(item,ItemStack.parseOptional(s.registryAccess(),o.item())));}
    public static void validateCitySale(MinecraftServer s,CargoWarehouseRegistry.Warehouse w,ItemStack item,long price){var b=book(s);if(b.binding()==null)return;var owner=CargoWarehouseRegistry.access(s,w).owner();if(owner.kind()!=OwnerRef.Kind.CITY||!owner.id().equals(b.binding().city()))return;for(var p:b.policies())if((p.direction()==MasterCityTradeBook.Direction.EXPORT||p.direction()==MasterCityTradeBook.Direction.BOTH)&&ItemStack.isSameItemSameComponents(item,ItemStack.parseOptional(s.registryAccess(),p.item()))&&price<=p.buyPrice())throw new IllegalArgumentException("master_city_resale_price");}
    public static boolean maySupply(ServerPlayer actor,CargoWarehouseRegistry.Warehouse w){var owner=CargoWarehouseRegistry.access(actor.getServer(),w).owner();return owner.kind()==OwnerRef.Kind.COMPANY?EconomyManager.get(actor.serverLevel()).companies().permits(owner.id(),actor.getUUID(),com.example.examplemod.economy.company.CompanyBook.Permission.TRADE):CargoWarehouseRegistry.manages(actor,w);}
    private static void automatic(MinecraftServer s,MasterCityTradeBook.Contract c){var b=book(s);int remaining=b.contractRemaining(c);if(remaining<1)return;var policy=b.policy(c.policy()).orElseThrow();var type=ItemStack.parseOptional(s.registryAccess(),policy.item());var commerce=EconomyManager.get(s.overworld()).cargo();var offers=commerce.offers().stream().filter(o->o.active()&&o.remaining()>0&&o.unitPrice()<=c.price()&&!o.warehouse().equals(b.binding().warehouse())&&!(o.owner().kind()==OwnerRef.Kind.CITY&&o.owner().id().equals(b.binding().city()))&&!b.isImportOffer(o.id())&&ItemStack.isSameItemSameComponents(type,ItemStack.parseOptional(s.registryAccess(),o.item()))).sorted(Comparator.comparingLong(CargoCommerceBook.Offer::unitPrice).thenComparing(CargoCommerceBook.Offer::id)).toList();for(var offer:offers){if(remaining<1)break;var access=CargoOwners.get(s).access("offer/"+offer.id(),offer.creator(),CargoTrainRegistry.AccessMode.PUBLIC);if(!CargoOwners.permits(s,payer(),access))continue;int quantity=Math.min(remaining,offer.remaining());UUID id=stable("auto/"+c.id()+"/"+offer.id()+"/"+remaining+"/"+(b.now()/60_000));try{supply(s,id,c,offer.id(),quantity);remaining=b.contractRemaining(c);}catch(IllegalArgumentException|NoSuchElementException invalid){b.note(null,"SUPPLIER_WAIT",offer.id()+": "+Objects.toString(invalid.getMessage(),"unavailable"));}}}
    private static SupplyQuote prepareSupply(ServerPlayer actor,UUID contractId,CompoundTag values){var s=actor.getServer();clock(s);var b=book(s);var c=b.contract(contractId).orElseThrow();if(!b.enabled())throw new IllegalArgumentException("master_paused");if(c.state()!=MasterCityTradeBook.ContractState.OPEN||c.expires()<b.now())throw new IllegalArgumentException("master_contract_changed");var p=b.policy(c.policy()).orElseThrow();int quantity=Integer.parseInt(values.getString("Quantity"));if(quantity<1||quantity>4096||quantity>b.contractRemaining(c))throw new IllegalArgumentException("master_contract_changed");var source=CargoWarehouseRegistry.get(s).find(UUID.fromString(values.getString("Source"))).orElseThrow();if(!maySupply(actor,source)||source.id().equals(b.binding().warehouse()))throw new IllegalArgumentException("master_supplier_denied");var owner=CargoWarehouseRegistry.access(s,source).owner();if(owner.kind()==OwnerRef.Kind.CITY&&owner.id().equals(b.binding().city()))throw new IllegalArgumentException("master_city_cannot_supply_itself");var ticker=CargoWarehouseRegistry.ticker(s,source);var type=ItemStack.parseOptional(s.registryAccess(),p.item());if(ticker==null||CargoFulfillment.available(s,source,type)<quantity)throw new IllegalArgumentException("delivery_stock_unavailable");var destination=warehouse(s);if((long)stock(s,destination,type)+b.inbound(p.id())+quantity>p.maximumStock())throw new IllegalArgumentException("master_stock_limit");var preference=CargoRoutePlanner.Preference.valueOf(values.contains("Preference")?values.getString("Preference"):"CHEAPEST");String service=values.contains("Service")?values.getString("Service"):"ANY";var route=CargoRoutePlanner.plan(s,payer(),source.point(),destination.point(),preference,service,quantity,type).orElseThrow(()->new IllegalArgumentException("delivery_route_unavailable"));long goods=Math.multiplyExact(c.price(),quantity);if(Math.addExact(goods,route.price())>Math.min(b.contractAvailable(c),Math.addExact(goods,p.maximumFreight())))throw new IllegalArgumentException("master_contract_budget");return new SupplyQuote(UUID.randomUUID(),s.overworld().getGameTime()+1200,c.id(),source,quantity,owner,goods,route);}
    public static CompoundTag quoteSupply(ServerPlayer actor,UUID contract,CompoundTag values){SupplyQuote quote;try{quote=prepareSupply(actor,contract,values);}catch(IllegalArgumentException|NoSuchElementException|ArithmeticException invalid){QUOTES.remove(actor);return blockedSupplyQuote(Objects.toString(invalid.getMessage(),"master_contract_changed"));}QUOTES.put(actor,quote);var s=actor.getServer();var b=book(s);var c=b.contract(contract).orElseThrow();var type=ItemStack.parseOptional(s.registryAccess(),b.policy(c.policy()).orElseThrow().item());var result=CargoFulfillment.routeQuote(actor,payer(),quote.source(),warehouse(s),type,quote.quantity(),quote.goods(),quote.route());result.putUUID("Token",quote.token());result.putBoolean("ExternalPayer",true);result.putString("PayerName","Внешнеторговый бюджет Моржеграда");result.put("MapValues",values.copy());return result;}
    private static CompoundTag blockedSupplyQuote(String problem){var result=new CompoundTag();result.putString("Status","BLOCKED");result.putBoolean("ExternalPayer",true);var checks=new ListTag();String blocked=problem.contains("stock")?"stock":problem.contains("budget")?"funds":problem.contains("denied")||problem.contains("permission")?"permissions":problem.contains("route")?"rail":problem.contains("infrastructure")?"receiver":"contract";for(String code:List.of("permissions","stock","receiver","rail","train","approach","return","funds","contract")){var check=new CompoundTag();check.putString("Code",code);check.putString("Status",code.equals(blocked)?"BLOCKED":"WARNING");check.putString("MessageKey","gui.createcityexpansioncore.logistics.check."+code);if(code.equals(blocked))check.putString("Detail",problem);check.putString("ActionKey","gui.createcityexpansioncore.logistics.check.fix");checks.add(check);}result.put("Checks",checks);return result;}
    public static void supply(ServerPlayer actor,UUID contractId,CompoundTag values,UUID request,UUID token){var s=actor.getServer();var b=book(s);UUID id=stable("public/"+actor.getUUID()+"/"+request);var old=b.supply(id).orElse(null);if(old!=null){if(!old.contract().equals(contractId)||old.quantity()!=Integer.parseInt(values.getString("Quantity")))throw new IllegalArgumentException("Supply identity conflict");return;}var expected=QUOTES.get(actor);if(expected==null||!expected.token().equals(token)||expected.expires()<s.overworld().getGameTime())throw new IllegalArgumentException("delivery_quote_expired");var current=prepareSupply(actor,contractId,values);if(!expected.contract().equals(current.contract())||!expected.source().equals(current.source())||expected.quantity()!=current.quantity()||!expected.supplier().equals(current.supplier())||expected.goods()!=current.goods()||!expected.route().equals(current.route()))throw new IllegalArgumentException("delivery_quote_changed");var c=b.contract(contractId).orElseThrow();var p=b.policy(c.policy()).orElseThrow();UUID offerId=stable("contract-offer/"+id);var commerce=EconomyManager.get(s.overworld()).cargo();if(commerce.offer(offerId).isEmpty())commerce.publish(offerId,actor.getUUID(),expected.supplier(),expected.source().id(),p.item(),p.name(),expected.quantity(),c.price());try{supply(s,id,c,offerId,expected.quantity(),expected.route());}finally{commerce.close(offerId);}QUOTES.remove(actor);b.note(actor.getUUID(),"CONTRACT_SUPPLY",c.id()+" / "+expected.quantity());}
    private static void supply(MinecraftServer s,UUID id,MasterCityTradeBook.Contract c,UUID offer,int quantity){supply(s,id,c,offer,quantity,null);}
    private static void supply(MinecraftServer s,UUID id,MasterCityTradeBook.Contract c,UUID offer,int quantity,CargoRoutePlanner.Route expectedRoute){var b=book(s);if(b.supply(id).isPresent())return;var w=warehouse(s);var p=b.policy(c.policy()).orElseThrow();var item=ItemStack.parseOptional(s.registryAccess(),p.item());if((long)stock(s,w,item)+b.inbound(p.id())+quantity>p.maximumStock())throw new IllegalArgumentException("master_stock_limit");var record=b.beginSupply(id,c.id(),offer,quantity,b.now());try(var funding=b.funding(record.id())){CargoFulfillment.purchase(s,id,payer(),offer,w.id(),quantity,expectedRoute);b.dispatched(id);}catch(Exception invalid){var order=EconomyManager.get(s.overworld()).cargo().order(id).orElse(null);if(order==null)b.resolved(id,0,0,true);else if(order.state()==CargoCommerceBook.State.REFUNDED)b.resolved(id,0,totalRefund(s,id),true);else b.failed(id,Objects.toString(invalid.getMessage(),"dispatch interrupted"));if(invalid instanceof RuntimeException runtime)throw runtime;throw new IllegalStateException(invalid);}}
    private static long totalRefund(MinecraftServer s,UUID id){var economy=EconomyManager.get(s.overworld());return Math.addExact(economy.cargo().refunded(id),economy.roadTolls().trip(id).map(t->t.getLong("Refunded")).orElse(0L));}
    public static void reconcile(MinecraftServer s){var b=book(s);if(b.binding()!=null){var w=CargoWarehouseRegistry.get(s).find(b.binding().warehouse()).orElse(null);if(w!=null)try{validateConfirmedImports(s,w);}catch(IllegalArgumentException ignored){/* No replay: unavailable or mismatched physical evidence blocks dispatch. */}}var commerce=EconomyManager.get(s.overworld()).cargo();var shipments=CargoShipmentRegistry.get(s);for(var supply:b.supplies()){if(supply.state()==MasterCityTradeBook.SupplyState.COMPLETED||supply.state()==MasterCityTradeBook.SupplyState.CANCELLED)continue;var order=commerce.order(supply.shipment()).orElse(null);var shipment=shipments.find(supply.shipment()).orElse(null);if(order==null){if(supply.charged()==0)b.resolved(supply.id(),0,0,true);else b.failed(supply.id(),"financial shipment missing");continue;}if(order.state()==CargoCommerceBook.State.SETTLED&&shipment!=null&&shipment.physicalComplete()&&com.example.examplemod.economy.EconomyManager.get(s.overworld()).roadTolls().tripClosed(order.id()))b.resolved(supply.id(),shipment.delivered(),totalRefund(s,order.id()),false);else if(order.state()==CargoCommerceBook.State.REFUNDED&&com.example.examplemod.economy.EconomyManager.get(s.overworld()).roadTolls().tripClosed(order.id()))b.resolved(supply.id(),0,totalRefund(s,order.id()),true);else if(order.state()==CargoCommerceBook.State.CANCELLED&&shipment!=null&&com.example.examplemod.economy.EconomyManager.get(s.overworld()).roadTolls().tripClosed(order.id()))b.resolved(supply.id(),shipment.delivered(),totalRefund(s,order.id()),true);}
        for(var c:b.contracts())if(c.state()==MasterCityTradeBook.ContractState.OPEN&&(b.contractRemaining(c)==0||b.now()>c.expires()))b.closeContract(c.id(),b.now()>c.expires(),null);
        if(b.binding()!=null)try{var customs=buffer(s);UUID pending=customs.buffer().pending();if(pending!=null){var batch=b.importBatch(pending).orElse(null);if(batch!=null&&batch.state()==MasterCityTradeBook.ImportState.CONFIRMED)customs.buffer().release(pending);else if(batch!=null&&batch.state()==MasterCityTradeBook.ImportState.ABANDONED)customs.buffer().resolve(pending,"Previously abandoned by operator");}}catch(IllegalArgumentException ignored){/* Replacing a customs block cannot authorize creation. */}
        for(var batch:b.imports())if(batch.state()==MasterCityTradeBook.ImportState.INTENT||batch.state()==MasterCityTradeBook.ImportState.APPLIED)try{confirmImport(s,batch.id(),null);}catch(IllegalArgumentException|NoSuchElementException ignored){/* A missing receipt never authorizes another creation. */}}
    private static boolean importGoods(MinecraftServer s,MasterCityTradeBook.Policy p,int quantity,UUID actor){var b=book(s);var target=buffer(s);var item=ItemStack.parseOptional(s.registryAccess(),p.item()).copyWithCount(quantity);if(target.buffer().capacity(item)!=quantity)return false;var batch=b.beginImport(stable("import/"+b.period()+"/"+p.id()+"/"+b.quotaUsed(p.id())),p.id(),quantity,actor);
        // Durable intent before touching chunk data: interrupted attempts are never replayed.
        EconomyManager.get(s.overworld()).setDirty();s.overworld().getDataStorage().save();net.neoforged.neoforge.common.IOUtilities.waitUntilIOWorkerComplete();
        target.buffer().create(batch.id(),item,p.item());b.importApplied(batch.id());return true;}
    public static void confirmImport(MinecraftServer s,UUID id,UUID actor){
        var b=book(s);var batch=b.importBatch(id).orElseThrow();if(batch.state()==MasterCityTradeBook.ImportState.CONFIRMED)return;if(batch.state()==MasterCityTradeBook.ImportState.ABANDONED||batch.state()==MasterCityTradeBook.ImportState.QUARANTINED&&actor==null)throw new IllegalArgumentException("master_import_changed");
        var target=buffer(s);var receipt=target.buffer().receipt(id);if(!MasterCityImportReceipts.matches(receipt,id,batch.item(),batch.quantity()))throw new IllegalArgumentException("master_import_receipt_missing");
        // Flush this single physical custody unit while it is still locked, before financial confirmation.
        if(!target.buffer().durable(id)){target.buffer().durable(id,true);target.setChanged();try{((net.minecraft.server.level.ServerLevel)target.getLevel()).getChunkSource().save(true);net.neoforged.neoforge.common.IOUtilities.waitUntilIOWorkerComplete();}catch(RuntimeException|Error failure){target.buffer().durable(id,false);throw failure;}}
        if(batch.state()==MasterCityTradeBook.ImportState.QUARANTINED)target.buffer().resolve(id,"Original physical receipt verified by "+actor);target.buffer().release(id);
        var w=warehouse(s);var policy=b.policy(batch.policy()).orElseThrow();var item=ItemStack.parseOptional(s.registryAccess(),batch.item());var commerce=EconomyManager.get(s.overworld()).cargo();UUID offer=stable("import-offer/"+id);var existing=commerce.offer(offer).orElse(null);int unsold=existing==null?batch.quantity():existing.remaining();if(stock(s,w,item)<unsold)throw new IllegalArgumentException("master_import_stock_not_linked");b.confirmImport(id,offer,actor);if(existing==null){var city=CityManager.get(s.overworld()).getCity(b.binding().city());UUID principal=city.getOwner();var cityOwner=new OwnerRef(OwnerRef.Kind.CITY,city.getId());commerce.publish(offer,principal,cityOwner,w.id(),batch.item(),policy.name(),batch.quantity(),policy.sellPrice());if(!CargoOwners.get(s).change(s,principal,"offer/"+offer,principal,CargoTrainRegistry.AccessMode.PUBLIC,new CargoOwners.Access(cityOwner,CargoTrainRegistry.AccessMode.PUBLIC,Set.of(),Set.of())))throw new IllegalStateException("Imported offer city ownership could not be registered");}else commerce.reopen(offer);
    }
    public static void closeImportListing(ServerPlayer actor,UUID id){requireOp(actor);var s=actor.getServer();UUID offer=book(s).closeImportListing(id,actor.getUUID());EconomyManager.get(s.overworld()).cargo().close(offer);}
    public static void closeContract(ServerPlayer actor,UUID id){requireOp(actor);var b=book(actor.getServer());if(b.supplies().stream().anyMatch(s->s.contract().equals(id)&&s.state()!=MasterCityTradeBook.SupplyState.COMPLETED&&s.state()!=MasterCityTradeBook.SupplyState.CANCELLED))throw new IllegalArgumentException("master_contract_in_transit");b.closeContract(id,false,actor.getUUID());}
    public static void abandonImport(ServerPlayer actor,UUID id,String reason){requireOp(actor);var s=actor.getServer();var b=book(s);var batch=b.importBatch(id).orElseThrow();if(reason==null||reason.isBlank())throw new IllegalArgumentException("master_recovery_reason_required");if(batch.state()==MasterCityTradeBook.ImportState.CONFIRMED)throw new IllegalArgumentException("master_import_changed");if(batch.offer()!=null){var commerce=EconomyManager.get(s.overworld()).cargo();commerce.close(batch.offer());for(var order:commerce.orders())if(batch.offer().equals(order.offer())&&order.state()!=CargoCommerceBook.State.SETTLED&&order.state()!=CargoCommerceBook.State.CANCELLED&&order.state()!=CargoCommerceBook.State.REFUNDED)CargoFulfillment.cancel(actor,order.id());}b.abandonImport(id,actor.getUUID(),reason);var target=batch.buffer().loaded(s);if(target instanceof MasterCityCustomsBufferBlockEntity customs&&(customs.buffer().pending()==null||id.equals(customs.buffer().pending())))customs.buffer().resolve(id,reason);}
    public static UUID stable(String value){return UUID.nameUUIDFromBytes(("ccec/master/"+value).getBytes(StandardCharsets.UTF_8));}
}


